<script setup lang="ts">
import {computed,ref,watch,type DeepReadonly} from 'vue';import type {SpeechSpeakers} from '../../shared/api/transcript-corrections';
const props=defineProps<{snapshot:DeepReadonly<SpeechSpeakers>;segments:readonly {segmentId:string;body:string;ordinal:number}[];busy:boolean;editable:boolean}>();
const emit=defineEmits<{label:[segmentIds:string[],label:string,enterpriseId:string|null];merge:[sourceId:string,targetId:string]}>();
const root=ref<HTMLElement>(),labelInput=ref<HTMLInputElement>();
const selected=ref<string[]>([]),label=ref(''),linked=ref<string|null>(null),source=ref(''),target=ref('');
watch(()=>props.snapshot.sourceRevisionId,()=>{selected.value=[];label.value='';linked.value=null;source.value='';target.value='';});
const disabled=computed(()=>props.busy||!props.editable),labels=computed(()=>new Map(props.snapshot.items.flatMap(x=>x.segmentIds.map(s=>[s,x.label] as const))));
function edit(id:string){const item=props.snapshot.items.find(x=>x.id===id);if(!item||disabled.value)return;selected.value=[...item.segmentIds];label.value=item.label;linked.value=item.enterpriseId;}
function submit(){if(disabled.value||!selected.value.length||!label.value.trim())return;emit('label',[...selected.value],label.value.trim(),linked.value);}
defineExpose({focus(){root.value?.scrollIntoView({block:'center',behavior:'smooth'});labelInput.value?.focus({preventScroll:true});}});
</script>
<template><section ref="root" class="speaker-workbench" aria-label="人工说话人标注"><header><h3>人工说话人标注</h3><span class="small muted">{{snapshot.items.length}} 个标签</span></header><p class="small muted">请结合原录音核对。标注、改名和合并均保留历史版本；标签不授予会议访问权限。</p><ul class="speaker-labels"><li v-for="speaker in snapshot.items" :key="speaker.id"><span>{{speaker.label}} · 人工标注 · {{speaker.segmentIds.length}} 段</span><button class="btn sm ghost" :disabled="disabled" @click="edit(speaker.id)">编辑说话人 {{speaker.label}}</button></li></ul><fieldset :disabled="disabled"><legend>选择需要标注的片段</legend><label v-for="segment in segments" :key="segment.segmentId" class="speaker-segment"><input v-model="selected" type="checkbox" :value="segment.segmentId"/><span>第 {{segment.ordinal}} 段 · {{labels.get(segment.segmentId)??'尚未标注'}} · {{segment.body.slice(0,50)}}</span></label><label class="field">说话人名称<input ref="labelInput" v-model="label" class="input" maxlength="256" aria-label="说话人名称"/></label><button class="btn sm" :disabled="!selected.length||!label.trim()" @click="submit">保存说话人标注</button></fieldset><fieldset v-if="snapshot.items.length>1" :disabled="disabled"><legend>合并当前稿件的说话人</legend><div class="merge-fields"><select v-model="source" class="select" aria-label="合并来源说话人"><option value="">选择来源</option><option v-for="speaker in snapshot.items" :key="speaker.id" :value="speaker.id">{{speaker.label}}</option></select><select v-model="target" class="select" aria-label="合并目标说话人"><option value="">选择目标</option><option v-for="speaker in snapshot.items" :key="speaker.id" :value="speaker.id">{{speaker.label}}</option></select><button class="btn sm" :disabled="!source||!target||source===target" @click="emit('merge',source,target)">合并说话人</button></div></fieldset></section></template>
<style scoped>.speaker-workbench{margin-top:16px;min-width:0}.speaker-workbench header,.speaker-labels li{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.speaker-workbench h3{font-size:14px}.speaker-labels{list-style:none;padding:0}.speaker-labels li{padding:6px 0}.speaker-workbench fieldset{min-width:0;border:1px solid var(--border);border-radius:6px;margin-top:12px;padding:12px}.speaker-workbench legend{font-size:12px;color:var(--muted)}.speaker-segment{display:flex;gap:8px;align-items:flex-start;margin:8px 0;overflow-wrap:anywhere}.speaker-segment input{flex:none}.speaker-workbench .field{margin:12px 0}.merge-fields{display:flex;gap:8px;flex-wrap:wrap}.merge-fields .select{min-width:0;max-width:100%;flex:1}</style>
